exports.push([module.i, "@charset \"UTF-8\";\n/**\n * 这里是uni-app内置的常用样式变量\n *\n * uni-app 官方扩展插件及插件市场（https://ext.dcloud.net.cn）上很多三方插件均使用了这些样式变量\n * 如果你是插件开发者，建议你使用scss预处理，并在插件代码中直接使用这些变量（无需 import 这个文件），方便用户通过搭积木的方式开发整体风格一致的App\n *\n */\n/**\n * 如果你是App开发者（插件使用者），你可以通过修改这些变量来定制自己的插件主题，实现自定义主题功能\n *\n * 如果你的项目同样使用了scss预处理，你也可以直接在你的 scss 代码中使用如下变量，同时无需 import 这个文件\n */\n/* 颜色变量 */\n/* 行为相关颜色 */\n/* 文字基本颜色 */\n/* 背景颜色 */\n/* 边框颜色 */\n/* 尺寸变量 */\n/* 文字尺寸 */\n/* 图片尺寸 */\n/* Border Radius */\n/* 水平间距 */\n/* 垂直间距 */\n/* 透明度 */\n/* 文章场景相关 */\n.home-container[data-v-bf47a6d4] {\n  min-height: 100vh;\n  background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);\n  position: relative;\n}\n.background-gradient[data-v-bf47a6d4] {\n  position: absolute;\n  top: 0;\n  left: 0;\n  right: 0;\n  height: 100%;\n  background: linear-gradient(135deg, #8B4513 0%, #D4AF37 100%);\n  z-index: 1;\n}\n.content-wrapper[data-v-bf47a6d4] {\n  position: relative;\n  z-index: 2;\n  box-sizing: border-box;\n  overflow: hidden;\n}\n.main-content[data-v-bf47a6d4] {\n  box-sizing: border-box;\n  overflow: hidden;\n  background: transparent;\n  padding: 0 30rpx;\n}\n/* 用户卡片样式 */\n.user-card[data-v-bf47a6d4] {\n  background: rgba(255, 255, 255, 0.95);\n  border-radius: 20rpx;\n  padding: 40rpx 30rpx;\n  margin-bottom: 30rpx;\n  box-shadow: 0 8rpx 32rpx rgba(0, 0, 0, 0.08);\n  -webkit-backdrop-filter: blur(10rpx);\n          backdrop-filter: blur(10rpx);\n}\n.user-header[data-v-bf47a6d4] {\n  display: flex;\n  align-items: center;\n  margin-bottom: 40rpx;\n}\n.avatar[data-v-bf47a6d4] {\n  width: 120rpx;\n  height: 120rpx;\n  border-radius: 50%;\n  border: 4rpx solid rgba(255, 255, 255, 0.8);\n  box-shadow: 0 8rpx 24rpx rgba(0, 0, 0, 0.1);\n}\n.user-basic-info[data-v-bf47a6d4] {\n  flex: 1;\n  margin-left: 30rpx;\n  display: flex;\n  flex-direction: column;\n}\n.username[data-v-bf47a6d4] {\n  font-size: 36rpx;\n  font-weight: bold;\n  color: #333;\n  margin-bottom: 10rpx;\n}\n.signature[data-v-bf47a6d4] {\n  font-size: 24rpx;\n  color: #666;\n  line-height: 1.4;\n}\n.signature.placeholder[data-v-bf47a6d4] {\n  color: #999;\n  font-style: italic;\n}\n.edit-text[data-v-bf47a6d4] {\n  margin-right: 8rpx;\n}\n.icon-arrow[data-v-bf47a6d4] {\n  font-size: 32rpx;\n  line-height: 1;\n}\n/* 菜单区域样式 */\n.menu-section[data-v-bf47a6d4] {\n  background: rgba(255, 255, 255, 0.95);\n  border-radius: 20rpx;\n  padding: 0;\n  margin-bottom: 30rpx;\n  box-shadow: 0 8rpx 32rpx rgba(0, 0, 0, 0.08);\n  overflow: hidden;\n}\n.menu-list .menu-item[data-v-bf47a6d4] {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 30rpx;\n  border-bottom: 1rpx solid #f5f5f5;\n  transition: all 0.3s ease;\n}\n.menu-list .menu-item[data-v-bf47a6d4]:active {\n  background: rgba(0, 0, 0, 0.03);\n}\n.menu-list .menu-item[data-v-bf47a6d4]:last-child {\n  border-bottom: none;\n}\n.menu-list .menu-item .menu-item-left[data-v-bf47a6d4] {\n  display: flex;\n  align-items: center;\n}\n.menu-list .menu-item .menu-icon[data-v-bf47a6d4] {\n  width: 50rpx;\n  height: 50rpx;\n  border-radius: 15rpx;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  margin-right: 20rpx;\n  font-size: 32rpx;\n}\n.menu-list .menu-item .menu-text[data-v-bf47a6d4] {\n  font-size: 30rpx;\n  color: #333;\n  font-weight: 500;\n}\n.menu-list .menu-item .menu-arrow[data-v-bf47a6d4] {\n  font-size: 36rpx;\n  color: #999;\n}\n/* 安全区域 */\n.safe-area[data-v-bf47a6d4] {\n  height: 20rpx;\n}", ""]);
